workflow.py<pre><code>import argparse
import json
import os
import time
from decimal import Decimal
from typing import Any, Callable
from uuid import uuid4
from confluent_kafka import Consumer
from fastapi import FastAPI
from pydantic import BaseModel, Field
import common

app = FastAPI()
TOPIC = "saga.events"
GROUPS = {"payment": "saga-payments", "inventory": "saga-inventory", "orders": "saga-orders", "shipping": "saga-shipping"}

class CheckoutRequest(BaseModel):
    customer_id: str
    sku: str
    quantity: int = Field(gt=0)
    amount: Decimal = Field(gt=0)
    fail_payment: bool = False
    fail_stock: bool = False

def enqueue(connection: Any, event: dict[str, Any]) -&gt; None:
    connection.execute(
        "INSERT INTO saga_outbox (aggregate_id, event_type, event_id, payload) VALUES (%s, %s, %s, %s) ON CONFLICT (event_id) DO NOTHING",
        (event["aggregate_id"], event["event_type"], event["event_id"], common.jsonb(event)),
    )

def emit(connection: Any, event_id: str, event_type: str, order_id: str, data: dict[str, Any]) -&gt; None:
    enqueue(connection, common.make_event(event_id, event_type, "checkout", order_id, data))

@app.post("/checkout")
def checkout(request: CheckoutRequest) -&gt; dict[str, str | int]:
    order_id = str(uuid4())
    event_id = f"order-{order_id}-placed"
    with common.connect() as connection:
        with connection.transaction():
            connection.execute(
                "INSERT INTO orders (order_id, customer_id, sku, quantity, amount, fail_payment, fail_stock) VALUES (%s, %s, %s, %s, %s, %s, %s)",
                (order_id, request.customer_id, request.sku, request.quantity, request.amount, request.fail_payment, request.fail_stock),
            )
            connection.execute("INSERT INTO order_pipeline (order_id) VALUES (%s)", (order_id,))
            emit(connection, event_id, "OrderPlaced", order_id, {"order_id": order_id, "customer_id": request.customer_id, "sku": request.sku, "quantity": request.quantity, "amount": str(request.amount), "fail_payment": request.fail_payment, "fail_stock": request.fail_stock})
    return {"order_id": order_id, "status": "new"}

def claim(connection: Any, group: str, event_id: str) -&gt; bool:
    return connection.execute(
        "INSERT INTO processed_events (consumer_group, event_id) VALUES (%s, %s) ON CONFLICT (consumer_group, event_id) DO NOTHING RETURNING event_id",
        (group, event_id),
    ).fetchone() is not None

def refund(connection: Any, order_id: str) -&gt; None:
    row = connection.execute("SELECT amount, captured, refunded FROM payments WHERE order_id = %s FOR UPDATE", (order_id,)).fetchone()
    if row is None or not row["captured"] or row["refunded"]:
        return
    connection.execute("UPDATE payments SET refunded = TRUE WHERE order_id = %s", (order_id,))
    connection.execute("UPDATE order_pipeline SET payment_refunded = 1 WHERE order_id = %s", (order_id,))
    emit(connection, f"payment-{order_id}-refunded", "PaymentRefunded", order_id, {"order_id": order_id, "amount": str(row["amount"])})

def release(connection: Any, order_id: str) -&gt; None:
    row = connection.execute("SELECT sku, quantity, released FROM reservations WHERE order_id = %s FOR UPDATE", (order_id,)).fetchone()
    if row is None or row["released"]:
        return
    connection.execute("UPDATE inventory SET available = available + %s, updated_at = now() WHERE sku = %s", (row["quantity"], row["sku"]))
    connection.execute("UPDATE reservations SET released = TRUE WHERE order_id = %s", (order_id,))
    connection.execute("UPDATE order_pipeline SET stock_released = 1 WHERE order_id = %s", (order_id,))
    emit(connection, f"stock-{order_id}-released", "StockReleased", order_id, {"order_id": order_id, "sku": row["sku"], "quantity": row["quantity"]})

def payment_handler(event: dict[str, Any]) -&gt; None:
    event_type = event["event_type"]
    if event_type not in {"OrderPlaced", "PaymentFailed", "StockFailed"}:
        return
    order_id = event["aggregate_id"]
    with common.connect() as connection:
        with connection.transaction():
            if not claim(connection, GROUPS["payment"], event["event_id"]):
                return
            order = connection.execute("SELECT amount, fail_payment FROM orders WHERE order_id = %s FOR UPDATE", (order_id,)).fetchone()
            state = connection.execute("SELECT stock_failed FROM order_pipeline WHERE order_id = %s FOR UPDATE", (order_id,)).fetchone()
            if order is None or state is None:
                raise RuntimeError(f"missing order {order_id}")
            if event_type == "OrderPlaced":
                if order["fail_payment"]:
                    connection.execute("UPDATE order_pipeline SET payment_failed = 1 WHERE order_id = %s", (order_id,))
                    emit(connection, f"payment-{order_id}-failed", "PaymentFailed", order_id, {"order_id": order_id, "reason": "injected-payment-failure"})
                else:
                    connection.execute("INSERT INTO payments (order_id, amount, captured) VALUES (%s, %s, TRUE) ON CONFLICT (order_id) DO NOTHING", (order_id, order["amount"]))
                    connection.execute("UPDATE order_pipeline SET payment_ok = 1 WHERE order_id = %s", (order_id,))
                    if state["stock_failed"] == 1:
                        refund(connection, order_id)
                    else:
                        emit(connection, f"payment-{order_id}-captured", "PaymentCaptured", order_id, {"order_id": order_id, "amount": str(order["amount"])})
            else:
                if event_type == "PaymentFailed":
                    connection.execute("UPDATE order_pipeline SET payment_failed = 1 WHERE order_id = %s", (order_id,))
                else:
                    connection.execute("UPDATE order_pipeline SET stock_failed = 1 WHERE order_id = %s", (order_id,))
                refund(connection, order_id)

def inventory_handler(event: dict[str, Any]) -&gt; None:
    event_type = event["event_type"]
    if event_type not in {"OrderPlaced", "PaymentFailed", "StockFailed"}:
        return
    order_id = event["aggregate_id"]
    with common.connect() as connection:
        with connection.transaction():
            if not claim(connection, GROUPS["inventory"], event["event_id"]):
                return
            order = connection.execute("SELECT sku, quantity, fail_stock FROM orders WHERE order_id = %s FOR UPDATE", (order_id,)).fetchone()
            state = connection.execute("SELECT payment_failed FROM order_pipeline WHERE order_id = %s FOR UPDATE", (order_id,)).fetchone()
            if order is None or state is None:
                raise RuntimeError(f"missing order {order_id}")
            if event_type == "OrderPlaced":
                updated = None
                if not order["fail_stock"]:
                    updated = connection.execute("UPDATE inventory SET available = available - %s, updated_at = now() WHERE sku = %s AND available &gt;= %s RETURNING sku", (order["quantity"], order["sku"], order["quantity"])).fetchone()
                if updated is None:
                    connection.execute("UPDATE order_pipeline SET stock_failed = 1 WHERE order_id = %s", (order_id,))
                    emit(connection, f"stock-{order_id}-failed", "StockFailed", order_id, {"order_id": order_id, "reason": "injected-stock-failure"})
                else:
                    connection.execute("INSERT INTO reservations (order_id, sku, quantity) VALUES (%s, %s, %s) ON CONFLICT (order_id) DO NOTHING", (order_id, order["sku"], order["quantity"]))
                    connection.execute("UPDATE order_pipeline SET stock_ok = 1 WHERE order_id = %s", (order_id,))
                    if state["payment_failed"] == 1:
                        release(connection, order_id)
                    else:
                        emit(connection, f"stock-{order_id}-reserved", "StockReserved", order_id, {"order_id": order_id, "sku": order["sku"], "quantity": order["quantity"]})
            else:
                if event_type == "PaymentFailed":
                    connection.execute("UPDATE order_pipeline SET payment_failed = 1 WHERE order_id = %s", (order_id,))
                else:
                    connection.execute("UPDATE order_pipeline SET stock_failed = 1 WHERE order_id = %s", (order_id,))
                release(connection, order_id)

def orders_handler(event: dict[str, Any]) -&gt; None:
    if event["event_type"] not in {"PaymentFailed", "StockFailed"}:
        return
    order_id = event["aggregate_id"]
    with common.connect() as connection:
        with connection.transaction():
            if not claim(connection, GROUPS["orders"], event["event_id"]):
                return
            state = connection.execute("SELECT cancelled FROM order_pipeline WHERE order_id = %s FOR UPDATE", (order_id,)).fetchone()
            if state is None:
                raise RuntimeError(f"missing order {order_id}")
            if state["cancelled"] == 0:
                connection.execute("UPDATE order_pipeline SET cancelled = 1 WHERE order_id = %s", (order_id,))
                connection.execute("UPDATE orders SET status = 'cancelled' WHERE order_id = %s", (order_id,))
                emit(connection, f"order-{order_id}-cancelled", "OrderCancelled", order_id, {"order_id": order_id, "reason": event["event_type"]})

def shipping_handler(event: dict[str, Any]) -&gt; None:
    event_type = event["event_type"]
    if event_type not in {"PaymentCaptured", "StockReserved", "PaymentFailed", "StockFailed"}:
        return
    order_id = event["aggregate_id"]
    with common.connect() as connection:
        with connection.transaction():
            if not claim(connection, GROUPS["shipping"], event["event_id"]):
                return
            if event_type == "PaymentCaptured":
                connection.execute("UPDATE order_pipeline SET payment_ok = 1 WHERE order_id = %s", (order_id,))
            elif event_type == "StockReserved":
                connection.execute("UPDATE order_pipeline SET stock_ok = 1 WHERE order_id = %s", (order_id,))
            elif event_type == "PaymentFailed":
                connection.execute("UPDATE order_pipeline SET payment_failed = 1 WHERE order_id = %s", (order_id,))
            else:
                connection.execute("UPDATE order_pipeline SET stock_failed = 1 WHERE order_id = %s", (order_id,))
            state = connection.execute("SELECT payment_ok, stock_ok, payment_failed, stock_failed, shipment_scheduled FROM order_pipeline WHERE order_id = %s FOR UPDATE", (order_id,)).fetchone()
            if state is None or state["payment_failed"] == 1 or state["stock_failed"] == 1:
                return
            if state["payment_ok"] == 1 and state["stock_ok"] == 1 and state["shipment_scheduled"] == 0:
                connection.execute("UPDATE order_pipeline SET shipment_scheduled = 1 WHERE order_id = %s", (order_id,))
                connection.execute("UPDATE orders SET status = 'confirmed' WHERE order_id = %s", (order_id,))
                emit(connection, f"order-{order_id}-confirmed", "OrderConfirmed", order_id, {"order_id": order_id})

def consume(group: str, handler: Callable[[dict[str, Any]], None]) -&gt; None:
    consumer = Consumer({"bootstrap.servers": os.environ["KAFKA_BOOTSTRAP_SERVERS"], "group.id": group, "auto.offset.reset": "earliest", "enable.auto.offset.commit": False})
    consumer.subscribe([TOPIC])
    try:
        while True:
            message = consumer.poll(1.0)
            if message is None:
                continue
            if message.error() is not None:
                raise RuntimeError(str(message.error()))
            handler(json.loads(message.value()))
            consumer.commit(message=message, asynchronous=False)
    finally:
        consumer.close()

def relay_once(connection: Any, producer: Any) -&gt; int:
    with connection.transaction():
        rows = connection.execute("SELECT id, payload FROM saga_outbox WHERE published = FALSE ORDER BY id LIMIT 100 FOR UPDATE SKIP LOCKED").fetchall()
        for row in rows:
            common.publish(producer, TOPIC, row["payload"])
        if rows:
            connection.execute("UPDATE saga_outbox SET published = TRUE WHERE id = ANY(%s)", ([row["id"] for row in rows],))
    return len(rows)

def relay(once: bool) -&gt; None:
    producer = common.new_producer("p06-saga-relay")
    with common.connect() as connection:
        while True:
            try:
                count = relay_once(connection, producer)
            except Exception as error:
                print(f"relay failed: {error}")
                if once:
                    raise
                time.sleep(1)
            else:
                if once:
                    return
                time.sleep(0.1 if count == 0 else 0)

def main() -&gt; None:
    parser = argparse.ArgumentParser()
    parser.add_argument("mode", choices=["relay", "payment", "inventory", "orders", "shipping"])
    parser.add_argument("--once", action="store_true")
    args = parser.parse_args()
    if args.mode == "relay":
        relay(args.once)
    else:
        consume(GROUPS[args.mode], {"payment": payment_handler, "inventory": inventory_handler, "orders": orders_handler, "shipping": shipping_handler}[args.mode])

if __name__ == "__main__":
    main()
</code></pre> <p>The four <code>consume</code> commands are independent groups even though they share a process. In production they are separate processes and databases. A crash after a local commit causes redelivery; the group-scoped claim makes the side effect once-only. The outbox relay publishes only after <code>common.publish</code> acknowledges each row.</p>

schema.sql<pre><code>CREATE TABLE IF NOT EXISTS processed_events (
  consumer_group TEXT NOT NULL, event_id TEXT NOT NULL,
  claimed_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (consumer_group, event_id)
);
CREATE TABLE IF NOT EXISTS order_effects (
  event_id TEXT PRIMARY KEY, order_id TEXT NOT NULL, payload JSONB NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS retry_jobs (
  job_id BIGSERIAL PRIMARY KEY, event_id TEXT NOT NULL, source_topic TEXT NOT NULL,
  message_key TEXT, raw_value TEXT NOT NULL, headers JSONB NOT NULL,
  attempt INTEGER NOT NULL CHECK (attempt &gt; 0), run_at TIMESTAMPTZ NOT NULL,
  state TEXT NOT NULL CHECK (state IN ('pending', 'published')),
  notified_at TIMESTAMPTZ, published_at TIMESTAMPTZ, last_error TEXT NOT NULL,
  UNIQUE (event_id, attempt)
);
CREATE INDEX IF NOT EXISTS retry_jobs_due_idx ON retry_jobs (run_at, job_id) WHERE state = 'pending';
CREATE TABLE IF NOT EXISTS dead_letters (
  dead_id BIGSERIAL PRIMARY KEY, event_id TEXT NOT NULL, source_topic TEXT NOT NULL,
  source_partition INTEGER NOT NULL, source_offset BIGINT NOT NULL, message_key TEXT,
  raw_value TEXT NOT NULL, payload JSONB, headers JSONB NOT NULL,
  error_class TEXT NOT NULL, error_detail TEXT NOT NULL, attempts INTEGER NOT NULL CHECK (attempts &gt; 0),
  published_at TIMESTAMPTZ, replayed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (source_topic, source_partition, source_offset, error_class)
);
</code></pre> <p><code>retry_jobs</code> is authoritative for scheduling. <code>dead_letters</code> is the durable index for the Kafka DLQ, so a crash between audit insert and DLQ publish is repairable without a consumer offset.</p>

reliability.py<pre><code>import argparse
import json
import os
import time
from datetime import datetime, timedelta, timezone
from typing import Any
from uuid import uuid4
from confluent_kafka import Consumer, Producer
import common

SOURCE_TOPIC = "orders.events"
RETRY_TOPIC = "orders.retry"
DEAD_TOPIC = "orders.dead"
GROUP = "orders-reliability"
MAX_ATTEMPTS = 4
BACKOFF_SECONDS = (1, 5, 15)

class TransientFailure(RuntimeError):
    pass

class PermanentFailure(RuntimeError):
    pass

def header_text(message: Any, name: str, default: str | None = None) -&gt; str | None:
    for key, value in message.headers() or []:
        if key == name:
            return (value or b"").decode("utf-8", errors="replace")
    return default

def headers_as_json(message: Any) -&gt; list[list[str]]:
    return [[key, (value or b"").decode("utf-8", errors="replace")] for key, value in message.headers() or []]

def replace_headers(headers: list[list[str]], additions: dict[str, str]) -&gt; list[tuple[str, bytes]]:
    names = set(additions)
    result = [(key, value.encode("utf-8")) for key, value in headers if key not in names]
    result.extend((key, value.encode("utf-8")) for key, value in additions.items())
    return result

def key_bytes(message: Any) -&gt; bytes | None:
    return message.key()

def key_text(message: Any) -&gt; str | None:
    key = message.key()
    return key.decode("utf-8", errors="replace") if key is not None else None

def value_bytes(message: Any) -&gt; bytes:
    return message.value() or b""

def publish_raw(producer: Producer, topic: str, key: bytes | None, value: bytes, headers: list[tuple[str, bytes]]) -&gt; None:
    errors: list[str] = []
    def delivered(error: object, message: object) -&gt; None:
        if error is not None:
            errors.append(str(error))
    producer.produce(topic, key=key, value=value, headers=headers, callback=delivered)
    remaining = producer.flush(15.0)
    if remaining != 0:
        raise TimeoutError(f"{remaining} Kafka record(s) remain undelivered")
    if errors:
        raise RuntimeError(errors[0])
    producer.poll(0)

def decode_event(message: Any) -&gt; dict[str, Any]:
    try:
        event = json.loads(value_bytes(message).decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise PermanentFailure(f"invalid-json: {error}") from error
    if not isinstance(event, dict):
        raise PermanentFailure("event must be a JSON object")
    for field in ("event_id", "aggregate_id", "event_type"):
        if not isinstance(event.get(field), str) or not event[field]:
            raise PermanentFailure(f"{field} is required")
    return event

def process_event(event: dict[str, Any]) -&gt; None:
    with common.connect() as connection:
        with connection.transaction():
            claimed = connection.execute(
                "INSERT INTO processed_events (consumer_group, event_id) VALUES (%s, %s) ON CONFLICT (consumer_group, event_id) DO NOTHING RETURNING event_id",
                (GROUP, event["event_id"]),
            ).fetchone()
            if claimed is None:
                return
            data = event.get("data")
            if not isinstance(data, dict):
                raise PermanentFailure("data must be an object")
            mode = data.get("fail_mode")
            if mode == "transient":
                raise TransientFailure("injected transient failure")
            if mode == "permanent":
                raise PermanentFailure("injected permanent failure")
            connection.execute(
                "INSERT INTO order_effects (event_id, order_id, payload) VALUES (%s, %s, %s)",
                (event["event_id"], event["aggregate_id"], common.jsonb(event)),
            )

def schedule_retry(message: Any, event: dict[str, Any], error: Exception, producer: Producer) -&gt; None:
    attempt = int(header_text(message, "x-attempts", "0") or 0) + 1
    if attempt &gt;= MAX_ATTEMPTS:
        dead_letter(message, event, "exhausted", str(error), attempt, producer)
        return
    run_at = datetime.now(timezone.utc) + timedelta(seconds=BACKOFF_SECONDS[attempt - 1])
    raw = value_bytes(message)
    headers = headers_as_json(message)
    with common.connect() as connection:
        with connection.transaction():
            job = connection.execute(
                """
                INSERT INTO retry_jobs (event_id, source_topic, message_key, raw_value, headers, attempt, run_at, state, last_error)
                VALUES (%s, %s, %s, %s, %s, %s, %s, 'pending', %s)
                ON CONFLICT (event_id, attempt) DO UPDATE SET last_error = EXCLUDED.last_error
                RETURNING job_id, notified_at
                """,
                (event["event_id"], SOURCE_TOPIC, key_text(message), raw.decode("utf-8", errors="replace"), common.jsonb(headers), attempt, run_at, str(error)),
            ).fetchone()
    if job["notified_at"] is not None:
        return
    wake_headers = replace_headers(headers, {"x-job-id": str(job["job_id"]), "x-attempts": str(attempt), "x-run-at": run_at.isoformat(), "x-error-class": "transient"})
    publish_raw(producer, RETRY_TOPIC, key_bytes(message), raw, wake_headers)
    with common.connect() as connection:
        with connection.transaction():
            connection.execute("UPDATE retry_jobs SET notified_at = now() WHERE job_id = %s", (job["job_id"],))

def dead_letter(message: Any, event: dict[str, Any] | None, error_class: str, detail: str, attempts: int, producer: Producer) -&gt; None:
    raw = value_bytes(message)
    partition = message.partition()
    offset = message.offset()
    event_id = event["event_id"] if event is not None else f"invalid-{message.topic()}-{partition}-{offset}"
    headers = replace_headers(headers_as_json(message), {"x-error-type": error_class, "x-attempts": str(attempts), "x-error-detail": detail, "x-source-partition-offset": f"{partition}/{offset}"})
    stored_headers = [[name, value.decode("utf-8", errors="replace")] for name, value in headers]
    with common.connect() as connection:
        with connection.transaction():
            row = connection.execute(
                """
                INSERT INTO dead_letters (event_id, source_topic, source_partition, source_offset, message_key, raw_value, payload, headers, error_class, error_detail, attempts)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                ON CONFLICT (source_topic, source_partition, source_offset, error_class) DO UPDATE SET error_detail = EXCLUDED.error_detail
                RETURNING dead_id, published_at
                """,
                (event_id, SOURCE_TOPIC, partition, offset, key_text(message), raw.decode("utf-8", errors="replace"), common.jsonb(event) if event is not None else None, common.jsonb(stored_headers), error_class, detail, attempts),
            ).fetchone()
    if row["published_at"] is not None:
        return
    publish_raw(producer, DEAD_TOPIC, key_bytes(message), raw, headers)
    with common.connect() as connection:
        with connection.transaction():
            connection.execute("UPDATE dead_letters SET published_at = now() WHERE dead_id = %s", (row["dead_id"],))

def retry_once(producer: Producer) -&gt; bool:
    with common.connect() as connection:
        with connection.transaction():
            job = connection.execute(
                "SELECT job_id, event_id, message_key, raw_value, headers, attempt FROM retry_jobs WHERE state = 'pending' AND notified_at IS NOT NULL AND run_at &lt;= now() ORDER BY run_at, job_id LIMIT 1 FOR UPDATE SKIP LOCKED"
            ).fetchone()
            if job is None:
                return False
            headers = replace_headers([[key, value] for key, value in job["headers"]], {"x-retry-of": job["event_id"], "x-job-id": str(job["job_id"]), "x-attempts": str(job["attempt"])})
            publish_raw(producer, SOURCE_TOPIC, job["message_key"].encode("utf-8") if job["message_key"] is not None else None, job["raw_value"].encode("utf-8"), headers)
            connection.execute("UPDATE retry_jobs SET state = 'published', published_at = now() WHERE job_id = %s", (job["job_id"],))
            return True

def retry_worker(once: bool) -&gt; None:
    producer = common.new_producer("p08-retry-worker")
    while True:
        try:
            changed = retry_once(producer)
        except Exception as error:
            print(f"retry worker failed: {error}")
            if once:
                raise
            time.sleep(1)
        else:
            if once:
                return
            time.sleep(0.5 if not changed else 0)

def consume() -&gt; None:
    producer = common.new_producer("p08-router")
    consumer = Consumer({"bootstrap.servers": os.environ["KAFKA_BOOTSTRAP_SERVERS"], "group.id": GROUP, "auto.offset.reset": "earliest", "enable.auto.offset.commit": False})
    consumer.subscribe([SOURCE_TOPIC])
    try:
        while True:
            message = consumer.poll(1.0)
            if message is None:
                continue
            if message.error() is not None:
                raise RuntimeError(str(message.error()))
            event: dict[str, Any] | None = None
            try:
                event = decode_event(message)
                process_event(event)
            except PermanentFailure as error:
                dead_letter(message, event, "invalid" if event is None else "permanent", str(error), 1, producer)
            except TransientFailure as error:
                schedule_retry(message, event, error, producer)
            except Exception as error:
                schedule_retry(message, event, TransientFailure(str(error)), producer)
            consumer.commit(message=message, asynchronous=False)
    finally:
        consumer.close()

def produce(failure_mode: str, event_id: str) -&gt; None:
    producer = common.new_producer("p08-producer")
    event = common.make_event(event_id, "OrderReceived", "order", event_id, {"order_id": event_id, "fail_mode": failure_mode})
    if failure_mode == "malformed":
        publish_raw(producer, SOURCE_TOPIC, event_id.encode("utf-8"), b'{"event_id":', [])
    else:
        common.publish(producer, SOURCE_TOPIC, event)
    print(event_id)

def replay(event_id: str | None, clear_failure: bool) -&gt; None:
    producer = common.new_producer("p08-replay")
    with common.connect() as connection:
        with connection.transaction():
            rows = connection.execute(
                "SELECT dead_id, event_id, message_key, raw_value, headers FROM dead_letters WHERE published_at IS NOT NULL AND replayed_at IS NULL AND (%s::text IS NULL OR event_id = %s) ORDER BY dead_id LIMIT 100 FOR UPDATE SKIP LOCKED",
                (event_id, event_id),
            ).fetchall()
            for row in rows:
                value = row["raw_value"].encode("utf-8")
                if clear_failure:
                    event = json.loads(value)
                    event["data"]["fail_mode"] = "none"
                    value = json.dumps(event, separators=(",", ":")).encode("utf-8")
                headers = replace_headers([[key, header] for key, header in row["headers"]], {"x-replay": "true", "x-original-event-id": row["event_id"]})
                publish_raw(producer, SOURCE_TOPIC, row["message_key"].encode("utf-8") if row["message_key"] is not None else None, value, headers)
                connection.execute("UPDATE dead_letters SET replayed_at = now() WHERE dead_id = %s", (row["dead_id"],))
    print(f"replayed {len(rows)} record(s)")

def main() -&gt; None:
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["produce", "consume", "retry", "replay"])
    parser.add_argument("--event-id")
    parser.add_argument("--failure-mode", default="none")
    parser.add_argument("--clear-failure", action="store_true")
    parser.add_argument("--once", action="store_true")
    args = parser.parse_args()
    event_id = args.event_id or str(uuid4())
    if args.command == "produce":
        produce(args.failure_mode, event_id)
    elif args.command == "consume":
        consume()
    elif args.command == "retry":
        retry_worker(args.once)
    else:
        replay(args.event_id, args.clear_failure)

if __name__ == "__main__":
    main()
</code></pre> <p>The retry worker is a PostgreSQL scheduler, not a future-bucket consumer. It publishes only due rows; a future row is never committed away from Kafka. The <code>orders.retry</code> record is a durable notification, while PostgreSQL remains the source of due-time state.</p>

